def graphs(s, x):
    import itertools
    (z, A, B, C, D) = ops(s, x)
    out = {'x': x, 'z': z, 'Ax': A(x)}
    bases = {k: out[k] for k in ('x', 'z', 'Ax')}
    funcs = dict(B=B, C=C, D=D)
    for (k, a) in bases.items():
        for n in (1, 2, 3):
            for seq in itertools.product(funcs, repeat=n):
                if n == 3 and len(set(seq)) < 3:
                    continue
                p = a
                for i in seq:
                    p = funcs[i](p)
                out[k + ''.join(seq)] = p
        (b, c, d) = (B(a), C(a), D(a))
        for (n, p, q) in [('BC', b, c), ('BD', b, d), ('CD', c, d), ('AC', a, c), ('AB', a, b), ('AD', a, d)]:
            out[k + n + 'cat'] = np.c_[p, q]
            out[k + n + 'plus'] = p + q
            out[k + n + 'minus'] = p - q
            out[k + n + 'mult'] = p * q
        out[k + 'BCDcat'] = np.c_[b, c, d]
        out[k + 'zBCDcat'] = np.c_[a, b, c, d]
    return out
